import requests
s=requests.Session()
for q in ['ID2 arsenic trioxide[Title/Abstract]','"inhibitor of DNA binding 2" AND arsenic trioxide','ID2 AND arsenic trioxide AND cancer']:
 r=s.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi',params={'db':'pubmed','term':q,'retmax':25,'retmode':'json'},timeout=25)
 print('\nQUERY',q,'HTTP',r.status_code,'BODY',r.text[:1000])
 try: ids=r.json().get('esearchresult',{}).get('idlist',[])
 except Exception as e: print('PARSE',e); continue
 if ids:
  t=s.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi',params={'db':'pubmed','id':','.join(ids),'rettype':'abstract','retmode':'text'},timeout=25)
  print('ABSTRACTS',t.status_code,t.text[:7000])
